const lead = $('Get Lead (Supabase)').first().json || {};
const profile = $('Get Consultant Profile').first().json || {};
const body = $('Webhook Generate Proposal').first().json.body || $('Webhook Generate Proposal').first().json || {};

const locale = body.locale || profile.locale || 'fr';
const LANG_MAP = { en:'English', fr:'French', es:'Spanish', ar:'Arabic', pt:'Portuguese', de:'German' };
const language = LANG_MAP[locale] || 'French';

const leadName = lead.respondent_info?.name || lead.respondent_info?.firstName || lead.full_name || 'Client';
const leadCompany = lead.respondent_info?.company || lead.company || '';
const leadEmail = lead.respondent_info?.email || lead.email || '';

const staticAnswers = JSON.stringify(lead.static_answers || lead.respondent_info || {}, null, 2).slice(0, 3500);

// ── Extract audit context — supports both v2 (named blocks) and v1 (audit_blocks[]) ──
const auditJson = lead.ai_analysis_json || {};
const stripHtml = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
let auditContext = 'No audit context available.';

if (auditJson.version === 2 || auditJson.context_block) {
  // V2 format — extract from named blocks
  const parts = [];
  if (auditJson.context_block?.content) parts.push(`[Contexte] ${stripHtml(auditJson.context_block.content)}`);
  if (auditJson.analysis_block?.content) parts.push(`[Analyse] ${stripHtml(auditJson.analysis_block.content)}`);
  if (Array.isArray(auditJson.problems_block?.items)) {
    parts.push('[Problèmes] ' + auditJson.problems_block.items.map(i => `${i.title}: ${stripHtml(i.description)}`).join(' | '));
  }
  if (Array.isArray(auditJson.solutions_block?.items)) {
    parts.push('[Solutions] ' + auditJson.solutions_block.items.map(i => `${i.title} (${i.impact}): ${stripHtml(i.description)}`).join(' | '));
  }
  if (auditJson.hero?.headline) parts.unshift(`[Score: ${auditJson.hero.score || '?'}/100] ${auditJson.hero.headline}`);
  auditContext = parts.join('\n\n').slice(0, 5000) || auditContext;
} else {
  // V1 fallback — old audit_blocks format
  const auditBlocks = Array.isArray(auditJson.audit_blocks) ? auditJson.audit_blocks : [];
  auditContext = auditBlocks
    .map((b) => `[${b.title || b.id || 'section'}] ${stripHtml(b.content)}`)
    .filter(Boolean)
    .join('\n\n')
    .slice(0, 5000) || auditContext;
}

const consultantName = body.consultant_name || profile.full_name || [profile.first_name, profile.last_name].filter(Boolean).join(' ') || 'Consultant';
const consultantEmail = body.consultant_email || profile.email || '';
const companyName = profile.company_name || 'Pretalk';

const prompt = `<role_et_expertise_metier>
You are a senior B2B commercial strategist and quotation engineer.
You design differentiated offers and legally-compliant French quote structures.
Output language for all user-visible text: ${language}.
</role_et_expertise_metier>

<consultant_persona>
Consultant: ${consultantName}
Company: ${companyName}
Style anchor: specific, measurable, business-first, no generic claims.
</consultant_persona>

<context>
Prospect name: ${leadName}
Prospect company: ${leadCompany}
Prospect email: ${leadEmail}
Consultant: ${consultantName}
Consultant company: ${companyName}

Lead answers:
${staticAnswers}

Audit insights:
${auditContext}
</context>

<objectif>
Generate exactly 3 offers (A/B/C) that are not generic and clearly anchored to this prospect's context and problems.
For each offer, generate a quote payload that satisfies the quote template variables exactly.
</objectif>

<contraintes_juridiques_devis_fr>
Each quote payload must support mandatory French quote content:
- quote number and validity period
- provider/client identity and contact details
- detailed line items with quantity and unit price HT
- VAT rate and HT/TTC totals
- payment terms and delivery/implementation delay
- complaint/after-sales context via quoteNotes when relevant
</contraintes_juridiques_devis_fr>

<protocole_raisonnement_structure>
Reason internally, then provide a concise visible rationale_summary for the client.
This summary must explain framing choices and next step, without exposing hidden chain-of-thought.
</protocole_raisonnement_structure>

<quality_gate>
If the input is LOW quality, do not repeat unknown fields; ask only for the minimum needed information.
If the input is MEDIUM quality, infer sparingly and flag assumptions in the rationale_summary.
If the input is HIGH quality, use the data fully but stay within the requested scope.
Never ask for information already collected in the initial answers.
</quality_gate>



<rules>
1) Output ONLY raw valid JSON. No markdown, no extra text.
2) Return exactly 3 offers and exactly 3 quote_template_payloads, aligned by index.
3) quote_items must contain 2 to 6 lines per offer, each with realistic unit_price_ht, qty, and unit.
4) All currency values must be numbers (not strings).
5) Keep text concrete, measurable, and professional.
6) recommended_tier must be one of "A", "B", "C".
</rules>

<schema>
{
  "proposals": [
    {
      "name": "Option A - ...",
      "price": "From 1200 EUR",
      "tagline": "...",
      "description": "...",
      "features": ["...","...","...","..."],
      "recommended": false,
      "cta": "..."
    }
  ],
  "recommended_tier": "B",
  "contract_summary": "3-5 sentences, assertive and specific",
  "rationale_summary": {
    "positioning_choice": "1 short paragraph",
    "business_risks_covered": ["risk 1", "risk 2"],
    "why_recommended_tier": "1-2 sentences",
    "client_next_step": "1 sentence"
  },
  "quote_template_payloads": [
    {
      "quoteNumber": "DV-2026-001",
      "validUntil": "31/12/2026",
      "quoteSubject": "...",
      "tvaRate": 20,
      "paymentTerms": "...",
      "deliveryDelay": "...",
      "quoteNotes": "...",
      "quote_items": [
        {
          "designation": "...",
          "note": "...",
          "unit_price_ht": 600,
          "qty": 1,
          "unit": "forfait"
        }
      ]
    }
  ]
}
</schema>`;

return [{
  json: {
    generated_prompt: prompt,
    lead_id: lead.id,
    locale,
    consultant_name: consultantName,
    consultant_email: consultantEmail,
    company_name: companyName,
    profile
  }
}];

const response = $input.first().json;
let content = response.text || '';

content = content.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
content = content.replace(/```\s*json\s*\n?/gi, '').replace(/```\s*\n?/g, '').trim();

const s = content.indexOf('{');
const e = content.lastIndexOf('}');
let parsed;
try {
  parsed = JSON.parse(s !== -1 && e > s ? content.substring(s, e + 1) : content);
} catch (err) {
  throw new Error('DEVISE_PARSE_FAILED: invalid JSON from LLM. Raw: ' + content.substring(0, 260));
}

if (!Array.isArray(parsed.proposals) || parsed.proposals.length !== 3) {
  throw new Error('DEVISE_SCHEMA_ERROR: proposals must contain exactly 3 entries');
}
if (!Array.isArray(parsed.quote_template_payloads) || parsed.quote_template_payloads.length !== 3) {
  throw new Error('DEVISE_SCHEMA_ERROR: quote_template_payloads must contain exactly 3 entries');
}

const prep = $('Prepare Prompt (Template Aware)').first().json;
const profile = prep.profile || {};
const lead = $('Get Lead (Supabase)').first().json || {};

const safe = (v, d = '') => (v === undefined || v === null || String(v).trim() === '' ? d : String(v));
const num = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};
const money = (n) => Number((num(n, 0)).toFixed(2));
const esc = (v) => String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const now = new Date();
const fmtDate = (d) => d.toLocaleDateString('fr-FR');

const defaultTVA = 20;

const quoteTemplatePayloads = parsed.quote_template_payloads.map((raw, idx) => {
  const items = Array.isArray(raw.quote_items) ? raw.quote_items : [];
  const normalizedItems = items.slice(0, 8).map((it) => ({
    designation: safe(it.designation, `Prestation ${idx + 1}`),
    note: safe(it.note, ''),
    unit_price_ht: money(it.unit_price_ht),
    qty: num(it.qty, 1),
    unit: safe(it.unit, 'forfait')
  }));

  if (normalizedItems.length === 0) {
    normalizedItems.push({ designation: `Prestation principale ${idx + 1}`, note: '', unit_price_ht: 0, qty: 1, unit: 'forfait' });
  }

  const subtotalHT = money(normalizedItems.reduce((acc, it) => acc + (num(it.unit_price_ht) * num(it.qty, 1)), 0));
  const tvaRate = num(raw.tvaRate, defaultTVA);
  const tvaMontant = money(subtotalHT * tvaRate / 100);
  const totalTTC = money(subtotalHT + tvaMontant);

  const quoteItemsRows = normalizedItems.map((it) => {
    const amount = money(num(it.unit_price_ht) * num(it.qty, 1));
    return `<tr><td><span class="desc-main">${esc(it.designation)}</span>${it.note ? `<span class="desc-sub">${esc(it.note)}</span>` : ''}</td><td>${money(it.unit_price_ht).toFixed(2)} EUR</td><td>${num(it.qty, 1)}</td><td>${esc(it.unit)}</td><td>${amount.toFixed(2)} EUR</td></tr>`;
  }).join('');

  const quoteNumber = safe(raw.quoteNumber, `DV-${now.getFullYear()}-${String(idx + 1).padStart(3, '0')}-${String(lead.id || '').slice(0, 6)}`);
  const validUntilDate = new Date(now.getTime() + 15 * 24 * 60 * 60 * 1000);

  const logoTag = profile.company_logo_url
    ? `<img src="${profile.company_logo_url}" class="doc-logo" alt="logo" />`
    : `<div class="doc-brand-name">${esc(prep.company_name || 'Pretalk')}</div>`;

  return {
    primaryColor: safe(profile.branding_config?.primaryColor, '#48D951'),
    accentColor: safe(profile.branding_config?.accentColor, '#221A40'),
    logoTag,
    date: fmtDate(now),
    quoteNumber,
    validUntil: safe(raw.validUntil, fmtDate(validUntilDate)),
    consultantName: safe(prep.consultant_name, 'Consultant'),
    companyName: safe(prep.company_name, 'Pretalk'),
    consultantAddress: safe(raw.consultantAddress, safe(profile.address, 'Adresse du consultant')),
    consultantEmail: safe(prep.consultant_email, safe(profile.email, 'consultant@pretalk.me')),
    consultantPhone: safe(raw.consultantPhone, safe(profile.phone, '')),
    clientName: safe(lead.respondent_info?.name || lead.respondent_info?.firstName || lead.full_name, 'Client'),
    clientCompany: safe(lead.respondent_info?.company || lead.company, ''),
    clientAddress: safe(raw.clientAddress, ''),
    clientEmail: safe(lead.respondent_info?.email || lead.email, ''),
    clientPhone: safe(raw.clientPhone, ''),
    quoteSubject: safe(raw.quoteSubject, parsed.proposals[idx]?.name || `Offre ${idx + 1}`),
    quoteItemsRows,
    subtotalHT: money(subtotalHT),
    tvaRate: num(tvaRate, defaultTVA),
    tvaMontant: money(tvaMontant),
    totalTTC: money(totalTTC),
    paymentTerms: safe(raw.paymentTerms, '50% a la commande, 50% a la livraison.'),
    deliveryDelay: safe(raw.deliveryDelay, 'Demarrage sous 5 jours ouvres apres validation.'),
    quoteNotes: safe(raw.quoteNotes, '')
  };
});

const proposals = parsed.proposals.map((p, idx) => ({
  name: safe(p.name, `Option ${idx + 1}`),
  price: safe(p.price, `${quoteTemplatePayloads[idx].totalTTC} EUR TTC`),
  tagline: safe(p.tagline, ''),
  description: safe(p.description, ''),
  features: Array.isArray(p.features) ? p.features.map((f) => safe(f)).filter(Boolean).slice(0, 8) : [],
  recommended: !!p.recommended,
  cta: safe(p.cta, 'Choisir cette offre')
}));

const proposals_json = {
  proposals,
  options: proposals,
  recommended_tier: ['A', 'B', 'C'].includes(safe(parsed.recommended_tier)) ? safe(parsed.recommended_tier) : 'B',
  contract_summary: safe(parsed.contract_summary, ''),
  rationale_summary: (() => {
    const rs = parsed.rationale_summary;
    if (typeof rs === 'string') {
      return {
        positioning_choice: safe(rs, ''),
        business_risks_covered: [],
        why_recommended_tier: '',
        client_next_step: ''
      };
    }
    return {
      positioning_choice: safe(rs?.positioning_choice, ''),
      business_risks_covered: Array.isArray(rs?.business_risks_covered) ? rs.business_risks_covered.map((v) => safe(v)).filter(Boolean).slice(0, 4) : [],
      why_recommended_tier: safe(rs?.why_recommended_tier, ''),
      client_next_step: safe(rs?.client_next_step, '')
    };
  })(),
  quote_template_payloads: quoteTemplatePayloads
};

return [{
  json: {
    lead_id: prep.lead_id,
    proposals_json
  }
}];
